escenas.drawCode:
drawBackgroundGrid(F, 0.15);
const A = F.area, cx = A.cx, cy = A.cy;
const p = ease(seg(t, 0, 1));
const pFail = ease(seg(t, F.at('fracasan'), F.at('fracasan') + 0.5));

// Planilla de cálculo rota en tiza
ctx.save();
ctx.strokeStyle = C.line;
ctx.lineWidth = 0.6;
const w = 70, h = 34, x0 = cx - w / 2, y0 = cy - h / 2 - 4;
rrect(x0, y0, w, h, 2);
ctx.stroke();

// Filas y columnas de celdas
for (let i = 1; i <= 4; i++) line(x0, y0 + (h / 5) * i, x0 + w, y0 + (h / 5) * i);
for (let j = 1; j <= 4; j++) line(x0 + (w / 5) * j, y0, x0 + (w / 5) * j, y0 + h);
ctx.restore();

// Celdas caóticas y errores
if (pFail > 0) {
  cross(cx - 14, cy - 8, 3.5 * pFail, pFail, C.warn);
  cross(cx + 14, cy + 2, 3.2 * pFail, pFail, C.warn);
  txt('#REF!', cx + 14, cy - 8, { size: 2.8, color: C.warn, family: FONT.mono, a: pFail });
  txt('NULL', cx - 14, cy + 2, { size: 2.8, color: C.muted, family: FONT.mono, a: pFail });
  bubble(cx + 25, cy - 14, 5 * pFail, '?', C.accent, pFail);
}

// Sello de fallo
txt('80%', cx, cy - 14, { size: 7 * p, color: C.warn, w: 700 });

drawBackgroundGrid(F, 0.15);
const A = F.area, cx = A.cx, cy = A.cy;
const pLine = ease(seg(t, F.at('dividimos'), F.at('dividimos') + 0.6));
const pAna = ease(seg(t, F.at('analista'), F.at('analista') + 0.5));
const pDis = ease(seg(t, F.at('diseñador'), F.at('diseñador') + 0.5));

// Línea de tiza central divisoria
if (pLine > 0) {
  ctx.save();
  ctx.strokeStyle = C.accent;
  ctx.lineWidth = 0.8;
  ctx.setLineDash([2, 2]);
  line(cx, cy - 25, cx, cy + 25 * pLine);
  ctx.restore();
}

// Lado izquierdo: Data Analyst
if (pAna > 0) {
  const xA = cx - 28, yA = cy - 2;
  person(xA, yA - 6, 7 * pAna, C.accent2, pAna);
  magnifier(xA + 10, yA - 2, 5 * pAna, pAna);
  txt('DATA ANALYST', xA, yA + 10, { size: 3.2, color: C.ink, family: FONT.mono, a: pAna, w: 700 });
  txt('Rigor & Calidad', xA, yA + 14, { size: 2.6, color: C.muted, a: pAna });
}

// Lado derecho: Dashboard Designer
if (pDis > 0) {
  const xD = cx + 28, yD = cy - 2;
  person(xD, yD - 6, 7 * pDis, C.accent, pDis);
  laptop(xD, yD + 2, 8 * pDis, pDis, 0.4);
  txt('DASHBOARD DESIGNER', xD, yD + 10, { size: 3.2, color: C.ink, family: FONT.mono, a: pDis, w: 700 });
  txt('Data Honesty & UI', xD, yD + 14, { size: 2.6, color: C.muted, a: pDis });
}

drawBackgroundGrid(F, 0.15);
const A = F.area, cx = A.cx, cy = A.cy;
const pRaw = ease(seg(t, 0, 0.8));
const pClean = ease(seg(t, F.at('limpiando'), F.at('limpiando') + 0.6));
const pOk = ease(seg(t, F.at('rota'), F.at('rota') + 0.5));

// Planillas de entrada
doc(cx - 24, cy - 14, 5 * pRaw, pRaw, 4);
doc(cx, cy - 16, 5.5 * pRaw, pRaw, 5);
doc(cx + 24, cy - 14, 5 * pRaw, pRaw, 4);

// Embudo de procesamiento
ctx.save();
ctx.strokeStyle = C.line;
ctx.lineWidth = 0.8;
ctx.beginPath();
ctx.moveTo(cx - 30, cy - 5);
ctx.lineTo(cx - 8, cy + 8);
ctx.lineTo(cx - 8, cy + 14);
ctx.stroke();
ctx.beginPath();
ctx.moveTo(cx + 30, cy - 5);
ctx.lineTo(cx + 8, cy + 8);
ctx.lineTo(cx + 8, cy + 14);
ctx.stroke();
ctx.restore();

// Bloques Parquet compactos y saneados
if (pClean > 0) {
  for (let b = -2; b <= 2; b++) {
    const bx = cx + b * 11, by = cy + 16;
    ctx.save();
    ctx.fillStyle = C.panel2;
    ctx.strokeStyle = C.accent2;
    ctx.lineWidth = 0.5;
    rrect(bx - 4.5, by - 3, 9, 6, 1.2);
    ctx.fill(); ctx.stroke();
    ctx.restore();
  }
  txt('PARQUET STREAMING', cx, cy + 8, { size: 2.8, color: C.accent2, family: FONT.mono, a: pClean });
}

if (pOk > 0) {
  checkBadge(cx + 30, cy + 16, 5 * pOk, pOk);
}

drawBackgroundGrid(F, 0.15);
const A = F.area, cx = A.cx, cy = A.cy;
const pCards = ease(seg(t, F.at('cinco'), F.at('cinco') + 0.6));
const pLock = ease(seg(t, F.at('dueño'), F.at('dueño') + 0.5));

// 5 tarjetas de KPI gobernadas
const count = 5;
const cardW = 12.5, gap = 2.5;
const startX = cx - ((count * cardW + (count - 1) * gap) / 2) + cardW / 2;

for (let i = 0; i < count; i++) {
  const x = startX + i * (cardW + gap);
  const y = cy - 2;
  const delay = i * 0.08;
  const pI = ease(seg(t, F.at('cinco') + delay, F.at('cinco') + delay + 0.4));
  if (pI <= 0) continue;

  ctx.save();
  ctx.fillStyle = C.panel;
  ctx.strokeStyle = (i === 0) ? C.accent : C.line;
  ctx.lineWidth = 0.6;
  rrect(x - cardW / 2, y - 10, cardW, 20, 2);
  ctx.fill(); ctx.stroke();
  ctx.restore();

  txt('KPI ' + (i + 1), x, y - 5, { size: 2.6, color: C.accent, family: FONT.mono, a: pI, w: 700 });
  line(x - cardW * 0.35, y - 1, x + cardW * 0.35, y - 1);
  txt('f(x)', x, y + 2, { size: 2.2, color: C.muted, family: FONT.mono, a: pI });

  if (pLock > 0) {
    padlock(x, y + 6, 2.2 * pLock, 1, pLock);
  }
}

drawBackgroundGrid(F, 0.15);
const A = F.area, cx = A.cx, cy = A.cy;
const pBuild = ease(seg(t, 0, 0.8));
const pSpark = ease(seg(t, F.at('vectoriales'), F.at('vectoriales') + 0.6));

// Carcasa del tablero
ctx.save();
ctx.strokeStyle = C.line;
ctx.fillStyle = C.panel;
ctx.lineWidth = 0.7;
rrect(cx - 40, cy - 22, 80, 44, 3);
ctx.fill(); ctx.stroke();

// Banda 1: KPIs con números tabulares
for (let k = 0; k < 3; k++) {
  const kx = cx - 26 + k * 26, ky = cy - 13;
  ctx.fillStyle = C.panel2;
  rrect(kx - 11, ky - 6, 22, 12, 1.5);
  ctx.fill();
  const vals = ['42 850', '98.4%', '2.3k'];
  txt(vals[k], kx, ky, { size: 3.6 * pBuild, color: C.ink, family: FONT.mono, w: 700 });
}

// Banda 2: Gráfico vectorial sin relleno de texto
const gx = cx - 36, gy = cy + 2, gw = 50, gh = 16;
ctx.strokeStyle = C.line;
ctx.lineWidth = 0.4;
line(gx, gy + gh, gx + gw, gy + gh);
line(gx, gy, gx, gy + gh);

// Curva SVG vectorial trazada
if (pSpark > 0) {
  ctx.strokeStyle = C.accent2;
  ctx.lineWidth = 1;
  ctx.beginPath();
  const pts = [[0, 12], [10, 9], [20, 11], [30, 4], [40, 6], [50, 2]];
  pts.forEach(([px, py], idx) => {
    const x = gx + (px / 50) * gw;
    const y = gy + (py / 16) * gh;
    idx === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
  });
  ctx.stroke();
}

// Panel lateral derecho: Desglose ordenado
for (let r = 0; r < 4; r++) {
  const ry = cy + 4 + r * 3.5;
  ctx.fillStyle = C.muted;
  ctx.fillRect(cx + 20, ry, 16 * (1 - r * 0.2) * pBuild, 1.6);
}
ctx.restore();

drawBackgroundGrid(F, 0.15);
const A = F.area, cx = A.cx, cy = A.cy;
const pNormal = ease(seg(t, 0, 0.6));
const pAlert = ease(seg(t, F.at('enciende'), F.at('enciende') + 0.4));

// Gráficos de viñeta (Bullet graphs) honestos
const rows = 3;
for (let i = 0; i < rows; i++) {
  const y = cy - 10 + i * 11;
  const isProblem = (i === 1);

  // Fondo neutral gris
  ctx.save();
  ctx.fillStyle = C.panel;
  rrect(cx - 36, y - 3.5, 72, 7, 1.5);
  ctx.fill();

  // Barra de rendimiento
  const valW = isProblem ? 22 : 46;
  ctx.fillStyle = (isProblem && pAlert > 0) ? C.warn : C.muted;
  rrect(cx - 34, y - 2, valW, 4, 1);
  ctx.fill();

  // Línea de meta (target)
  ctx.strokeStyle = C.ink;
  ctx.lineWidth = 0.8;
  line(cx + 8, y - 3, cx + 8, y + 3);

  // Acción directa en la alerta
  if (isProblem && pAlert > 0) {
    ring(cx + 24, y, 4 * pAlert, pAlert, C.accent, 0.8);
    arrow(cx + 10, y, cx + 20, y, pAlert, C.accent, 0.8);
    txt('ACT', cx + 24, y, { size: 2.2, color: C.accent, family: FONT.mono, w: 700 });
  }
  ctx.restore();
}

drawBackgroundGrid(F, 0.15);
const A = F.area, cx = A.cx, cy = A.cy;
const pIn = ease(seg(t, 0, 0.7));
const pBoard = ease(seg(t, F.at('directorio'), F.at('directorio') + 0.6));
const pCheck = ease(seg(t, F.at('decisión'), F.at('decisión') + 0.5));

// Conector de narrativa (flecha dinámica de la métrica a la decisión)
arrow(cx - 34, cy + 2, cx - 12, cy - 2, pIn, C.accent2, 1);

// Carpeta ejecutiva / Presentación de decisiones
if (pBoard > 0) {
  const bx = cx + 14, by = cy - 2;
  ctx.save();
  ctx.fillStyle = C.panel;
  ctx.strokeStyle = C.accent;
  ctx.lineWidth = 0.7;
  rrect(bx - 18, by - 14, 36, 28, 2);
  ctx.fill(); ctx.stroke();

  txt('DECISIÓN EJECUTIVA', bx, by - 9, { size: 2.5, color: C.accent, family: FONT.mono, w: 700 });
  line(bx - 14, by - 6, bx + 14, by - 6);

  // 3 puntos accionables
  for (let c = 0; c < 3; c++) {
    const cyRow = by - 1 + c * 5.5;
    if (pCheck > 0) check(bx - 10, cyRow, 1.8 * pCheck, pCheck);
    ctx.fillStyle = C.ink;
    ctx.fillRect(bx - 6, cyRow - 0.7, 18 * pBoard, 1.4);
  }
  ctx.restore();
}

drawBackgroundGrid(F, 0.2);
const A = F.area, cx = A.cx, cy = A.cy;
const pFlow = ease(seg(t, 0, 1));
const pBadge = ease(seg(t, F.at('transparente'), F.at('transparente') + 0.5));

// 4 estaciones del pipeline continuo
const steps = ['INGESTA', 'GOBERNANZA', 'DISEÑO UI', 'DECISIÓN'];
const r = 26;
for (let s = 0; s < 4; s++) {
  const ang = (s / 4) * TAU - Math.PI / 2;
  const sx = cx + Math.cos(ang) * (r * 1.3);
  const sy = cy + Math.sin(ang) * (r * 0.75);

  ctx.save();
  ctx.fillStyle = C.panel;
  ctx.strokeStyle = C.accent;
  ctx.lineWidth = 0.7;
  rrect(sx - 11, sy - 5, 22, 10, 2);
  ctx.fill(); ctx.stroke();

  txt(steps[s], sx, sy, { size: 2.3 * pFlow, color: C.ink, family: FONT.mono, w: 700 });
  ctx.restore();

  // Flechas entre pasos
  const nextAng = ((s + 1) / 4) * TAU - Math.PI / 2;
  const nx = cx + Math.cos(nextAng) * (r * 1.3);
  const ny = cy + Math.sin(nextAng) * (r * 0.75);
  arrow(sx, sy, nx, ny, pFlow * 0.6, C.line, 0.6);
}

// Sello central de Data Honesty y transparencia
if (pBadge > 0) {
  checkBadge(cx, cy, 7 * pBadge, pBadge);
  txt('DATA HONESTY', cx, cy + 9, { size: 2.8, color: C.ok, family: FONT.mono, w: 700, a: pBadge });
}
